export { CFBReader, DirectoryObjectType, DirectoryEntryTreeItem, DirectoryEntry } from "./cfb";


enum FieldName {
  SubStgVersion1 = "__substg1.0",
  PrTransportMessageHeaders = "007D",
  senderEmail = "5D02",
