  ProviderSubmitTime = "0048",
  CreationTime = "3007",
  LastModificationTime = "3008",
  MessageDeliverTime = "0E06",
  SenderEmailAddress = "0C1F",
  SenderName = "0C1A",
  SenderSmtpAddress = "5D01",
  SenderAddressType = "0C1E",
